Translate("ruRU", "velarok-windblade", {
	title = "Веларок Клинок Ветра",
	subtitle = "Человек, поклявшийся отомстить",
	found = [=[К югу от Лагеря Братства Тория, возле изувеченных останков дворфов Черного Железа]=],
	hint = [=[Отыщите незнакомца, который ждет среди мертвых дворфов Черного Железа к югу от Лагеря Братства Тория.]=],
	allegiance = "Собственное дело",
	aliases = { "Веларок", "Каларан Клинок Ветра" },
	sections = {
		{
			title = "Обзор",
			text = [=[Веларок Клинок Ветра пришел в {link:searing-gorge}Тлеющее ущелье{/link} ради мести — так он, по крайней мере, говорит. Он рассказывает об отце, убитом {link:dwarves}дворф{/link}ами Черного Железа из {link:the-cauldron}Котлован{/link}а, и о мольбах о правосудии, которые не пожелали услышать судьи {link:stormwind-city}Штормград{/link}а. Королевство, горько говорит он, скорее сделает вид, что этого уголка мира не существует, чем пошлет сюда своих солдат. Поэтому он пришел сам, и с ним нет никого, кроме неуклюжего оруженосца, и он ждет того, кто окажется достаточно смел, чтобы помочь ему нанести удар.]=],
		},
		{
			title = "Значение",
			text = [=[Веларок предлагает то, что в ущелье встретишь редко: план. Он не собирается биться с {link:dwarves}дворф{/link}ами Черного Железа клинок к клинку. Он намерен сперва ослепить их, спалив сторожевые башни, что стерегут {link:the-cauldron}Котлован{/link}, а затем ударить, пока они не опомнились. Тем, кто ему поможет, он сулит богатства, о каких они и не мечтали.]=],
		},
		{
			title = "Деяния",
			text = [=[• Он рассказывает свою историю всякому путнику, готовому слушать.
• Он собирает сердца пламени и масло големов для факела, который не погасит ни одна стихия.
• Он переплавляет ториевые кинжалы работорговцев Черного Железа, чтобы выковать древко факела.
• Он вытягивает магию из символа, посвященного владыке {red:ragnaros}Рагнаросу{/red} и отнятого у Сумеречного Молота, чтобы сделать оправу факела.]=],
		},
	},
	chapters = {
		{
			title = "Факел возмездия",
			hint = [=[Соберите то, что нужно для факела, и посмотрите, как его делают.]=],
			text = [=[Факел был сделан из самого ущелья. Его пламя взято из сердец огненных элементалей и масла боевых големов. Его древко выковано из зачарованного тория, из клинков самих работорговцев. Его оправа сработана из идола Повелителя Огня, чью скверную магию Веларок счел идеальной для такого дела. Он долго склонялся над частями и велел помощнику набраться терпения. Когда работа была кончена, всякий, кто поднимал факел, чувствовал, как сквозь него проходят волны ненависти и гнева.]=],
		},
		{
			title = "Обманщик",
			hint = "Подожгите четыре башни Котлована.",
			text = [=[Башни горели, и оруженосец кричал, что это великолепно. Тогда Веларок сбросил человеческий облик. Он был драконом из черной стаи, и никакого убитого отца никогда не было. Ему нужно было лишь, чтобы первая линия обороны клана Черного Железа была уничтожена, и он знал, что ни один смертный не помог бы легиону {link:blackrock-clan}Черной горы{/link}, попроси он прямо. Он пощадил тех, кто ему послужил, чтобы они дожили до хаоса грядущего вторжения в ущелье. Он оставил им груду безделушек, а с ней — сброшенную шкуру черного дракона, которой, по его словам, его сородичи в {link:burning-steppes}Пылающих степях{/link} могут укрепить свои изделия. Затем он взмыл в небо и полетел к {link:blackrock-mountain}Черной горе{/link}.]=],
		},
	},
	mentions = {
		{ text = "«Божественное возмездие»" },
		{ text = "«Безупречное пламя»" },
		{ text = "«Ковка древка»" },
		{ text = "«Оболочка пламени»" },
		{ text = "«Факел Возмездия»" },
		{ text = "«Факел Возмездия», факел, привязанный к своему носителю" },
