Translate("ruRU", "dorius-stonetender", {
	title = "Дориус Камнетес",
	subtitle = "Археолог Стальгорна",
	found = "Дно Карьера Грязнули",
	hint = "Ищите раненого дворфа на дне Карьера Грязнули.",
	allegiance = "Королевство Стальгорн",
	aliases = { "Дориус" },
	sections = {
		{
			title = "Обзор",
			text = [=[Дориус Камнетес привел в {link:searing-gorge}Тлеющее ущелье{/link} отряд землекопов Стальгорна. Его брат — куратор Ториус из Зала Исследователей. Когда пришли {link:dwarves}дворф{/link}ы Черного Железа, его отряд захватили, а Дориус остался, раненый и истекающий кровью, в яме Карьера Грязнули. Он умоляет любого прохожего помочь ему добраться до ворот в {link:loch-modan}Лок Модан{/link} и до дороги домой, в {link:ironforge}Стальгорн{/link}.]=],
		},
		{
			title = "Значение",
			text = [=[Дориус отправился искать камни, называемые Сунтара, — реликвии, которых желал и {link:dark-iron-dwarves}клан Черного Железа{/link}. Его участь толкает его скорбящего брата на путь мести и втягивает {link:ironforge}Стальгорн{/link} в тайны {link:the-cauldron}Котлован{/link}а.]=],
		},
		{
			title = "Деяния",
			text = [=[• Он привел в ущелье отряд археологов {link:ironforge}Стальгорн{/link}а.
• Он оставил в {link:the-cauldron}Котлован{/link}е метку, чтобы его люди не пропали там навеки.
• Он пробивался к воротам Подгорной тропы, несмотря на раны.]=],
		},
	},
	chapters = {
		{
			title = "Опаленное письмо",
			hint = [=[Помогите раненому добраться до безопасного места и доставьте то, что он оставит после себя.]=],
			text = [=[Дориус не дошел до ворот. Когда тропа уже показалась впереди, грянул выстрел, и он упал. После него осталось письмо с опаленными краями, адресованное брату. В нем он писал, что камни существуют, что ими владеют {link:dwarves}дворф{/link}ы Черного Железа и что их предводитель, Латорик Черный, пользуется их силой, чтобы поработить отряд землекопов. Его людей увели в {link:the-cauldron}Котлован{/link}. Их разум искажен ради одной-единственной задачи — создания чего-то, называемого {link:obsidion}Обсидион{/link}. Освободи их, просил он. Когда Ториус прочел это, он заплакал и именем {link:holy-light}Свет{/link}а поклялся, что последняя воля брата будет исполнена.]=],
		},
		{
			title = "Алтарь Сунтары",
			hint = "Спуститесь в Шлаковую Яму на поиски пропавших археологов.",
			text = [=[Археологов нашли в глубине Шлаковой Ямы: они все еще работали, хотя их тела отказывали. Один из них, умирая, объяснил, что сила камней Сунтары заставит их довершать свой труд даже после смерти. Освободить их мог только алтарь Сунтары, но ему недоставало реликвии, которую {link:twilight-s-hammer}Сумеречный Молот{/link} хранил в холмах Гряды Огненной стражи. Реликвию отняли у сектантов и возложили на алтарь.]=],
		},
		{
			title = "Латорик Черный",
			hint = "Посмотрите, что пробудит алтарь Сунтары.",
			text = [=[Все это было западней. Дориус вовсе не умирал. Когда он нашел камни Сунтары в Карьере Грязнули, сквозь него хлынула сила Повелителя Огня, и {red:ragnaros}Рагнарос{/red} дал ему новую цель и новое имя: Латорик Черный. Он сыграл на горе своего брата, чтобы заманить в ущелье спасателей, которые отобьют для него последний камень у Сумеречного Молота. Голем {link:obsidion}Обсидион{/link} создан волей Повелителя Огня, хвалился он, чтобы уничтожить {link:orcs}орк{/link}ов Вершины Черной горы и воссоединить его с собратьями в огненных глубинах. Затем он велел голему восстать. Когда Ториус узнал правду, лицо его побелело. Брат предал и его, и весь {link:ironforge}Стальгорн{/link}, и Ториус устрашился: если столь благородного {link:dwarves}дворф{/link}а можно было так легко обратить, то в безопасности нет никого.]=],
		},
	},
	mentions = {
		{ text = "«Камни Сунтары»" },
		{ text = "«Камни Сунтары», опаленное письмо" },
		{ text = "«Дворфийское правосудие»" },
		{ text = "«Освободить их»" },
		{ text = "«Восстань, {link:obsidion}Обсидион{/link}!»" },
	},
	bonds = {
		{ id = "curator-thorius", name = "Куратор Ториус", note = "его брат" },
		{ id = "obsidion", name = "Обсидион", note = "голем, которого заставили строить его людей" },
	},
})

